  if (listId === 'free') headBoxY = gridY - 20;
  else if (listId === 'L2') headBoxY = gridY + 40;
  else headBoxY = gridY + 100;

  let headBoxRight = gridX - 102;
  let firstColX = gridX + (path[0] - 1) * 50 + 25;

  // Arrow from head to first node
  if (listId === 'free') {
    arrowGroup.path(`M ${headBoxRight} ${headBoxY + 19} Q ${gridX - 20} ${gridY - 30} ${firstColX} ${gridY - 20}`)
      .fill('none').stroke({color: arrowColor, width: 3, linejoin: 'round'}).marker('end', `#${mId}`);
  } else {
    let outX = gridX - 30;
    let downY = (listId === 'L2') ? gridY + 155 : gridY + 185;
    arrowGroup.path(`M ${headBoxRight} ${headBoxY + 19} C ${outX} ${headBoxY + 19}, ${outX} ${downY}, ${firstColX} ${downY} L ${firstColX} ${gridY + 128}`)
      .fill('none').stroke({color: arrowColor, width: 3, linejoin: 'round'}).marker('end', `#${mId}`);
  }

  // Inter-node arrows
  for (let i = 0; i < path.length - 1; i++) {
    let curr = path[i];
    let nxt = path[i+1];
    let cx = gridX + (curr - 1) * 50 + 25;
    let nx = gridX + (nxt - 1) * 50 + 25;

    let dist = Math.abs(nx - cx);
    let midX = (cx + nx) / 2;

    // Next pointer arrow (top)
    let curveY = gridY - 25 - dist * 0.08;
    arrowGroup.path(`M ${cx} ${gridY - 2} Q ${midX} ${curveY} ${nx} ${gridY - 22}`)
      .fill('none').stroke({color: arrowColor, width: 2, linejoin: 'round'}).marker('end', `#${mId}`);

    // Prev pointer arrow (bottom)
    if (listId !== 'free') {
      let curveYBot = gridY + 120 + 15 + dist * 0.05;
      arrowGroup.path(`M ${nx} ${gridY + 122} Q ${midX} ${curveYBot} ${cx} ${gridY + 130}`)
        .fill('none').stroke({color: arrowColor, width: 2, dasharray: '5,3', linejoin: 'round'}).marker('end', `#${mId}`);
    }
  }
}

function buildScene() {
  draw.clear();
  colGroups = [];
  headGroups = [];
  const memState = STATES[appState.step];

  // Labels
  draw.text('next').attr({x: gridX - 10, y: gridY + 26, 'text-anchor': 'end'}).font({family: 'Times', size: 20, style: 'italic'});
  draw.text('key').attr({x: gridX - 10, y: gridY + 66, 'text-anchor': 'end'}).font({family: 'Times', size: 20, style: 'italic'});
  draw.text('prev').attr({x: gridX - 10, y: gridY + 106, 'text-anchor': 'end'}).font({family: 'Times', size: 20, style: 'italic'});

  for (let i = 0; i < 10; i++) {
    draw.text(String(i+1)).attr({x: gridX + i * 50 + 25, y: gridY - 8, 'text-anchor': 'middle'}).font({family: 'Times', size: 18});
  }

  // Master Grid Background
  draw.rect(500, 120).move(gridX, gridY).fill('#000');

  // Columns
  for (let i = 0; i < 10; i++) {
    const colData = memState.memory[i];
    const x = gridX + i * 50;
    const colGroup = draw.group();
    colGroups.push({ group: colGroup, list: colData.list, index: i + 1 });

    for (let row = 0; row < 3; row++) {
      const y = gridY + row * 40;
      colGroup.rect(48, 38).move(x + 1, y + 1).fill(colorMap[colData.list]);
    }

    // Next
    if (colData.next !== '') {
      colGroup.text(colData.next)
        .attr({x: x + 25, y: gridY + 26, 'text-anchor': 'middle'})
        .font({family: 'Times', size: 18}).fill(textColorMap[colData.list]);

      if (colData.next !== '/') {
        let overlay = colGroup.rect(48, 38).move(x + 1, gridY + 1).fill('transparent').css('cursor', 'pointer');
        overlay.on('mouseenter', (e) => {
          setHover(i + 1, parseInt(colData.next));
          showTooltip(`next pointer connects to slot ${colData.next}`, e.originalEvent || e);
        });
        overlay.on('mouseleave', () => { setHover(null, null); hideTooltip(); });
      }
    }

    // Key
    if (colData.key === '') {
      colGroup.line(x + 10, gridY + 60, x + 40, gridY + 60).stroke({color: textColorMap[colData.list], width: 2, dasharray: '3,3'});
    } else {
      let kt = colGroup.text(add => {
        add.tspan('k').font({style: 'italic'});
        add.tspan(colData.key).attr('dy', 5).font({size: 13});
      }).font({family: 'Times', size: 18}).fill(textColorMap[colData.list]);
      kt.attr({x: x + 16, y: gridY + 66});
    }

    // Prev
    if (colData.prev === '' && colData.list === 'free') {
      colGroup.line(x + 10, gridY + 100, x + 40, gridY + 100).stroke({color: textColorMap[colData.list], width: 2, dasharray: '3,3'});
    } else if (colData.prev !== '') {
      colGroup.text(colData.prev)
        .attr({x: x + 25, y: gridY + 106, 'text-anchor': 'middle'})
        .font({family: 'Times', size: 18}).fill(textColorMap[colData.list]);

      if (colData.prev !== '/') {
        let overlay = colGroup.rect(48, 38).move(x + 1, gridY + 81).fill('transparent').css('cursor', 'pointer');
        overlay.on('mouseenter', (e) => {
          setHover(i + 1, parseInt(colData.prev));
          showTooltip(`prev pointer connects back to slot ${colData.prev}`, e.originalEvent || e);
        });
        overlay.on('mouseleave', () => { setHover(null, null); hideTooltip(); });
      }
    }
  }

  // Heads
  const configs = [
    { list: 'free', label: 'free', y: gridY - 20, sub: '' },
    { list: 'L2', label: 'L', y: gridY + 40, sub: '2' },
    { list: 'L1', label: 'L', y: gridY + 100, sub: '1' }
  ];

  configs.forEach(c => {
    let hg = draw.group().css('cursor', 'pointer');
    headGroups.push({ group: hg, list: c.list });

    hg.on('click', () => {
      appState.activeTrace = (appState.activeTrace === c.list) ? null : c.list;
      drawArrows();
      updateOpacities();
    });
    hg.on('mouseenter', (e) => showTooltip(`Trace ${c.label === 'free' ? 'the free list' : c.label + ' ' + c.sub} sequence`, e.originalEvent || e));
    hg.on('mouseleave', hideTooltip);

    hg.text(add => {
      add.tspan(c.label).font({style: 'italic'});
      if (c.sub) add.tspan(c.sub).attr('dy', 5).font({size: 14});
    }).font({family: 'Times', size: 24}).attr({x: gridX - 160, y: c.y + 26, 'text-anchor': 'end'});

    hg.rect(48, 38).move(gridX - 150, c.y).fill(colorMap[c.list]);
    hg.rect(48, 38).move(gridX - 150, c.y).fill('none').stroke({width: 2, color: '#000'});

    hg.text(String(STATES[appState.step].heads[c.list]))
      .attr({x: gridX - 126, y: c.y + 26, 'text-anchor': 'middle'})
      .font({family: 'Times', size: 18}).fill(textColorMap[c.list]);
  });

  arrowGroup = draw.group();
  drawArrows();
  updateOpacities();
}

window.update_memoryOperation = function(val) {
  let targetStep = 0;
  if (val === 'Allocate slot') targetStep = 2;
  else if (val === 'Free slot') targetStep = 3;

  if (window.currentStep !== targetStep && val !== steps[window.currentStep].state.memoryOperation) {
    window.currentStep = targetStep;
    renderStep();
    return;
  }

  appState.step = targetStep === 2 ? 1 : targetStep === 3 ? 2 : 0;
  appState.activeTrace = null;
  buildScene();
};

const steps = [
  {
    title: "Interleaved Lists",
    narration: "Three separate lists—L₁, L₂, and the free list—share the same physical arrays. Click on the L₁ or L₂ head pointers to trace their logical sequences.",
    state: { memoryOperation: "Initial" }
  },
  {
    title: "The Free List",
    narration: "Click the 'free' head to trace the available slots. The free list strings together empty columns using only the 'next' array.",
    state: { memoryOperation: "Initial" }
  },
  {
    title: "Allocation",
    narration: "When allocating, the first available slot (index 10) is popped from the free list and repurposed for a data list, updating pointers instead of moving memory.",
    state: { memoryOperation: "Allocate slot" }
  },
  {
    title: "Freeing Memory",
    narration: "When a node is freed (like slot 6), it is unlinked from its list and its index is pushed onto the free list, making it available again.",
    state: { memoryOperation: "Free slot" }
  }
];

window.currentStep = 0;

function renderStep() {
  const step = steps[window.currentStep];
  document.getElementById('demoNarration').innerHTML = `<strong>${step.title}:</strong> ${step.narration}`;
  document.getElementById('stepLabel').textContent = `Step ${window.currentStep + 1} of ${steps.length}`;

  let memInput = document.getElementById('memoryOperationInput');
  if (memInput.value !== step.state.memoryOperation) {
    memInput.value = step.state.memoryOperation;
    window.update_memoryOperation(step.state.memoryOperation);
  }

  if (window.currentStep === 0) appState.activeTrace = 'L1';
  else if (window.currentStep === 1) appState.activeTrace = 'free';
  else if (window.currentStep === 2) appState.activeTrace = 'L1'; // L1 grew
  else if (window.currentStep === 3) appState.activeTrace = 'free'; // slot 6 added to free

  buildScene();
}

window.prevStep = function() {
  if (window.currentStep > 0) {
    window.currentStep--;
    renderStep();
  }
};

window.nextStep = function() {
  if (window.currentStep < steps.length - 1) {
    window.currentStep++;
    renderStep();
  }
};

renderStep();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Multiple linked lists can be interleaved within the same parallel arrays by using array indices as pointers, with a 'free' list tracking available storage.
KEY INSIGHT (what students should walk away understanding): Using array indices as pointers allows multiple dynamic data structures to coexist and share memory in a static array without shifting data around.
DEMO STEPS: 4 guided steps — implement the step player in #ui

