// @FIGURE_CODE_BEGIN
const W = 800;
const H = 350;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

const gridX = 220;
const gridY = 80;

const colorMap = { 'free': '#000000', 'L2': '#959595', 'L1': '#e4e4e4' };
const textColorMap = { 'free': '#ffffff', 'L2': '#000000', 'L1': '#000000' };

const STATES = [
  { // 0: Initial
    heads: { free: 10, L2: 9, L1: 3 },
    memory: [
      { list: 'L2', next: '5', key: '1', prev: '7' },
      { list: 'L1', next: '/', key: '2', prev: '6' },
      { list: 'L1', next: '6', key: '3', prev: '/' },
      { list: 'free', next: '8', key: '', prev: '' },
      { list: 'L2', next: '/', key: '5', prev: '1' },
      { list: 'L1', next: '2', key: '6', prev: '3' },
      { list: 'L2', next: '1', key: '7', prev: '9' },
      { list: 'free', next: '/', key: '', prev: '' },
      { list: 'L2', next: '7', key: '9', prev: '/' },
      { list: 'free', next: '4', key: '', prev: '' }
    ]
  },
  { // 1: Allocate (slot 10 pops from free list and goes to L1 head)
    heads: { free: 4, L2: 9, L1: 10 },
    memory: [
      { list: 'L2', next: '5', key: '1', prev: '7' },
      { list: 'L1', next: '/', key: '2', prev: '6' },
      { list: 'L1', next: '6', key: '3', prev: '10' },
      { list: 'free', next: '8', key: '', prev: '' },
      { list: 'L2', next: '/', key: '5', prev: '1' },
      { list: 'L1', next: '2', key: '6', prev: '3' },
      { list: 'L2', next: '1', key: '7', prev: '9' },
      { list: 'free', next: '/', key: '', prev: '' },
      { list: 'L2', next: '7', key: '9', prev: '/' },
      { list: 'L1', next: '3', key: '10', prev: '/' }
    ]
  },
  { // 2: Free (slot 6 unlinked from L1 and pushed to free list)
    heads: { free: 6, L2: 9, L1: 10 },
    memory: [
      { list: 'L2', next: '5', key: '1', prev: '7' },
      { list: 'L1', next: '/', key: '2', prev: '3' },
      { list: 'L1', next: '2', key: '3', prev: '10' },
      { list: 'free', next: '8', key: '', prev: '' },
      { list: 'L2', next: '/', key: '5', prev: '1' },
      { list: 'free', next: '4', key: '', prev: '' },
      { list: 'L2', next: '1', key: '7', prev: '9' },
      { list: 'free', next: '/', key: '', prev: '' },
      { list: 'L2', next: '7', key: '9', prev: '/' },
      { list: 'L1', next: '3', key: '10', prev: '/' }
    ]
  }
];

let appState = {
  step: 0,
  activeTrace: null,
  hoverTarget: null,
  hoverSource: null
};

let colGroups = [];
let headGroups = [];
let arrowGroup = null;
let myArrowMarker = null;

function setHover(src, tgt) {
  appState.hoverSource = src;
  appState.hoverTarget = tgt;
  updateOpacities();
}

function updateOpacities() {
  colGroups.forEach(cg => {
    let dim = false;
    if (appState.hoverTarget !== null) {
      dim = (cg.index !== appState.hoverSource && cg.index !== appState.hoverTarget);
    } else if (appState.activeTrace !== null) {
      dim = (cg.list !== appState.activeTrace);
    }
    cg.group.opacity(dim ? 0.2 : 1);
  });

  headGroups.forEach(hg => {
    let dim = false;
    if (appState.hoverTarget !== null) {
      dim = true;
    } else if (appState.activeTrace !== null) {
      dim = (hg.list !== appState.activeTrace);
    }
    hg.group.opacity(dim ? 0.2 : 1);
  });
}

function getListPath(state, listId) {
  let headVal = state.heads[listId];
  if (headVal === '/' || headVal === '') return [];
  let path = [];
  let curr = headVal;
  while (curr !== '/' && curr !== '' && path.length < 20) {
    path.push(parseInt(curr));
    curr = state.memory[parseInt(curr) - 1].next;
  }
  return path;
}

function drawArrows() {
  if (arrowGroup) arrowGroup.clear();
  if (appState.activeTrace === null) return;

  const memState = STATES[appState.step];
  const listId = appState.activeTrace;
  const path = getListPath(memState, listId);
  if (path.length === 0) return;

  let arrowColor = '#e85d04';
  let headBoxY;
  if (listId === 'free') headBoxY = gridY;
  else if (listId === 'L2') headBoxY = gridY + 40;
  else headBoxY = gridY + 80;

  let headBoxRight = gridX - 102;
  let firstColX = gridX + (path[0] - 1) * 50 + 25;
  let startX = headBoxRight;
  let startY = headBoxY + 19;

  if (listId === 'free') {
    arrowGroup.path(`M ${startX} ${startY} C ${startX + 30} ${startY}, ${gridX - 20} ${gridY - 25}, ${firstColX} ${gridY - 25} L ${firstColX} ${gridY - 2}`)
      .fill('none').stroke({color: arrowColor, width: 3, linejoin: 'round'}).marker('end', myArrowMarker);
  } else {
    let downY = (listId === 'L2') ? gridY + 145 : gridY + 175;
    arrowGroup.path(`M ${startX} ${startY} C ${startX + 30} ${startY}, ${startX + 30} ${downY}, ${firstColX} ${downY} L ${firstColX} ${gridY + 122}`)
      .fill('none').stroke({color: arrowColor, width: 3, linejoin: 'round'}).marker('end', myArrowMarker);
  }

  for (let i = 0; i < path.length - 1; i++) {
    let curr = path[i];
    let nxt = path[i+1];
    let cx = gridX + (curr - 1) * 50 + 25;
    let nx = gridX + (nxt - 1) * 50 + 25;

    let dist = Math.abs(nx - cx);
    let midX = (cx + nx) / 2;

    let curveY = gridY - 25 - dist * 0.08;
    arrowGroup.path(`M ${cx} ${gridY - 2} Q ${midX} ${curveY} ${nx} ${gridY - 22}`)
      .fill('none').stroke({color: arrowColor, width: 2, linejoin: 'round'}).marker('end', myArrowMarker);

    if (listId !== 'free') {
      let curveYBot = gridY + 120 + 15 + dist * 0.05;
      arrowGroup.path(`M ${nx} ${gridY + 122} Q ${midX} ${curveYBot} ${cx} ${gridY + 130}`)
        .fill('none').stroke({color: arrowColor, width: 2, dasharray: '5,3', linejoin: 'round'}).marker('end', myArrowMarker);
    }
  }
}

function drawNullPointer(group, x, y, listType) {
  group.line(x + 12, y + 28, x + 38, y + 12).stroke({ 
    color: textColorMap[listType], 
    width: 3, 
    linecap: 'round' 
  });
}

function buildScene() {
  draw.clear();
  colGroups = [];
  headGroups = [];
  const memState = STATES[appState.step];

  myArrowMarker = draw.marker(10, 10, function(add) {
    add.path('M0,0 L10,5 L0,10 L2,5 Z').fill('#e85d04');
  }).ref(8, 5).orient('auto');

  draw.text('next').attr({x: gridX - 10, y: gridY + 26, 'text-anchor': 'end'}).font({family: 'Times', size: 20, style: 'italic'});
  draw.text('key').attr({x: gridX - 10, y: gridY + 66, 'text-anchor': 'end'}).font({family: 'Times', size: 20, style: 'italic'});
  draw.text('prev').attr({x: gridX - 10, y: gridY + 106, 'text-anchor': 'end'}).font({family: 'Times', size: 20, style: 'italic'});

  for (let i = 0; i < 10; i++) {
    draw.text(String(i+1)).attr({x: gridX + i * 50 + 25, y: gridY - 8, 'text-anchor': 'middle'}).font({family: 'Times', size: 18});
  }

  draw.rect(500, 120).move(gridX, gridY).fill('#000');

  for (let i = 0; i < 10; i++) {
    const colData = memState.memory[i];
    const x = gridX + i * 50;
    const colGroup = draw.group();
    colGroups.push({ group: colGroup, list: colData.list, index: i + 1 });

    if (colData.list === 'free') {
      colGroup.rect(50, 120).move(x, gridY).fill('#000');
    } else {
      for (let row = 0; row < 3; row++) {
        const y = gridY + row * 40;
        colGroup.rect(48, 38).move(x + 1, y + 1).fill(colorMap[colData.list]);
      }
    }

    if (colData.next === '/') {
      drawNullPointer(colGroup, x, gridY, colData.list);
    } else if (colData.next !== '') {
      colGroup.text(colData.next)
        .attr({x: x + 25, y: gridY + 26, 'text-anchor': 'middle'})
        .font({family: 'Times', size: 18}).fill(textColorMap[colData.list]);

      let overlay = colGroup.rect(48, 38).move(x + 1, gridY + 1).fill('transparent').css('cursor', 'pointer');
      overlay.on('mouseenter', (e) => {
        setHover(i + 1, parseInt(colData.next));
        showTooltip(`next pointer connects to slot ${colData.next}`, e.originalEvent || e);
      });
      overlay.on('mouseleave', () => { setHover(null, null); hideTooltip(); });
    }

    if (colData.list === 'free') {
      colGroup.line(x, gridY + 60, x + 50, gridY + 60).stroke({color: '#fff', width: 2, dasharray: '2,3'});
    } else if (colData.key !== '') {
      let kt = colGroup.text(add => {
        add.tspan('k').font({style: 'italic'});
        add.tspan(colData.key).attr('dy', 5).font({size: 13, style: 'normal'});
      }).font({family: 'Times', size: 18}).fill(textColorMap[colData.list]);
      kt.attr({x: x + 25, y: gridY + 66, 'text-anchor': 'middle'});
    }

    if (colData.list === 'free') {
      colGroup.line(x, gridY + 100, x + 50, gridY + 100).stroke({color: '#fff', width: 2, dasharray: '2,3'});
    } else if (colData.prev === '/') {
      drawNullPointer(colGroup, x, gridY + 80, colData.list);
    } else if (colData.prev !== '') {
      colGroup.text(colData.prev)
        .attr({x: x + 25, y: gridY + 106, 'text-anchor': 'middle'})
        .font({family: 'Times', size: 18}).fill(textColorMap[colData.list]);

      let overlay = colGroup.rect(48, 38).move(x + 1, gridY + 81).fill('transparent').css('cursor', 'pointer');
      overlay.on('mouseenter', (e) => {
        setHover(i + 1, parseInt(colData.prev));
        showTooltip(`prev pointer connects back to slot ${colData.prev}`, e.originalEvent || e);
      });
      overlay.on('mouseleave', () => { setHover(null, null); hideTooltip(); });
    }
  }

  const configs = [
    { list: 'free', label: 'free', y: gridY, sub: '' },
    { list: 'L2', label: 'L', y: gridY + 40, sub: '2' },
    { list: 'L1', label: 'L', y: gridY + 80, sub: '1' }
  ];

  configs.forEach(c => {
    let hg = draw.group().css('cursor', 'pointer');
    headGroups.push({ group: hg, list: c.list });

    hg.on('click', () => {
      appState.activeTrace = (appState.activeTrace === c.list) ? null : c.list;
      drawArrows();
      updateOpacities();
    });
    hg.on('mouseenter', (e) => showTooltip(`Trace ${c.label === 'free' ? 'the free list' : c.label + ' ' + c.sub} sequence`, e.originalEvent || e));
    hg.on('mouseleave', hideTooltip);

    hg.text(add => {
      add.tspan(c.label).font({style: 'italic'});
      if (c.sub) add.tspan(c.sub).attr('dy', 5).font({size: 14});
    }).font({family: 'Times', size: 24}).attr({x: gridX - 160, y: c.y + 26, 'text-anchor': 'end'});

    hg.rect(48, 38).move(gridX - 150, c.y).fill(colorMap[c.list]).stroke({width: 1, color: '#000'});

    hg.text(String(STATES[appState.step].heads[c.list]))
      .attr({x: gridX - 126, y: c.y + 26, 'text-anchor': 'middle'})
      .font({family: 'Times', size: 18}).fill(textColorMap[c.list]);
  });

  arrowGroup = draw.group();
  drawArrows();
  updateOpacities();
}

const steps = [
  {
    title: "Interleaved Lists",
    narration: "Three separate lists—L₁, L₂, and the free list—share the same physical arrays. Click on the L₁ or L₂ head pointers to trace their logical sequences.",
    state: { memoryOperation: "Initial" }
  },
  {
    title: "The Free List",
    narration: "Click the 'free' head to trace the available slots. The free list strings together empty columns using only the 'next' array.",
    state: { memoryOperation: "Initial" }
  },
  {
    title: "Allocation",
    narration: "When allocating, the first available slot (index 10) is popped from the free list and repurposed for a data list, updating pointers instead of moving memory.",
    state: { memoryOperation: "Allocate slot" }
  },
  {
    title: "Freeing Memory",
    narration: "When a node is freed, it is unlinked from its list and its index is pushed onto the free list, making it available again.",
    state: { memoryOperation: "Free slot" }
  }
];

window.currentStep = 0;

window.update_memoryOperation = function(val) {
  let targetStep = val === 'Allocate slot' ? 2 : val === 'Free slot' ? 3 : 0;
  if (window.currentStep !== targetStep) {
    window.currentStep = targetStep;
    renderStep();
  }
};

function renderStep() {
  const step = steps[window.currentStep];
  document.getElementById('demoNarration').innerHTML = `<strong>${step.title}:</strong> ${step.narration}`;
