                  step.state.memoryOperation === 'Free slot' ? 2 : 0;

  if (window.currentStep === 0) appState.activeTrace = 'L1';
  else if (window.currentStep === 1) appState.activeTrace = 'free';
  else if (window.currentStep === 2) appState.activeTrace = 'L1';
  else if (window.currentStep === 3) appState.activeTrace = 'free';

  buildScene();
}

